import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    for i in range(n):
        a.append(int(input_data[1 + i]))

    max_erased = 0

    # Try erasing every possible consecutive segment from index i to j (inclusive)
    # where 0 <= i <= j < n
    for i in range(n):
        for j in range(i, n):
            # Check if erasing elements from index i to j is valid
            # Validity conditions:
            # 1. If i > 0, the gap between a[i-1] and a[j+1] must be fillable with strictly increasing integers.
            #    The number of missing elements is (j - i + 1).
            #    The available range is a[j+1] - a[i-1] - 1.
            #    We need: a[j+1] - a[i-1] - 1 >= (j - i + 1)
            #    Simplified: a[j+1] - a[i-1] >= j - i + 2

            # 2. If i == 0, we need to be able to fill from 1 up to a[j+1] with (j - i + 1) numbers.
            #    The range available is a[j+1] - 1.
            #    We need: a[j+1] - 1 >= (j - i + 1)
            #    Simplified: a[j+1] >= j - i + 2

            # 3. If j < n-1, we need to be able to fill from a[i] up to 1000 with (j - i + 1) numbers.
            #    The range available is 1000 - a[i].
            #    We need: 1000 - a[i] >= (j - i + 1)
            #    Simplified: 1000 - a[i] >= j - i + 1

            can_erase = True

            if i > 0:
                if a[j+1] - a[i-1] - 1 < (j - i + 1):
                    can_erase = False
            if can_erase and j < n - 1:
                if 1000 - a[i] < (j - i + 1):
                    can_erase = False
            if can_erase and i == 0:
                if a[j+1] - 1 < (j - i + 1):
                    can_erase = False

            if can_erase:
                count = j - i + 1
                if count > max_erased:
                    max_erased = count

    print(max_erased)

if __name__ == "__main__":
    solve()
